    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_sami" to DuaText("感覚の悪から逃れる", "アッラーよ、私は聴覚の悪、視覚の悪、舌の悪、心の悪、欲望の悪からあなたに避難を求めます。", "シャカル・イブン・フメイド(RA)に教えられた。", "罪から手足と身を守るドゥア。"),
        "dua_hadm_gharaq" to DuaText("突然死や事故からの避難", "アッラーよ、私はあなたに（建物に）押しつぶされたり、高所から落ちたり、溺れたり、火傷したり、老衰したりすることからの避難を求めます。死の際に私を迷わせたシャイタンから、あなたの道から逃げて死んだこと、そして（毒の）刺し傷で死んだことから。", "事故や不運な死から逃れましょう。", "預言者 ﷺ からの避難のドゥア。"),
        "dua_ju_khiyanah" to DuaText("飢餓と裏切りからの避難", "アッラーよ、私はあなたに飢えからの避難を求めます、それは邪悪な仲間だからです、そして私はあなたに裏切りからの避難を求めます、それは邪悪な腹心だからです。", "飢えと裏切りから逃げましょう。", "預言者 ﷺ からの避難のドゥア。"),
        "dua_huda_tuqa" to DuaText("導き、信心深さ、貞操、そして十分さ", "おおアッラーよ、私はあなたに導き、敬虔さ、純潔、そして自給自足をお願いします。", "Prophet ﷺ の短く包括的なデュア。", "宗教とこの世の 4 つの基本的な祝福。"),
        "dua_aslih_li_dini" to DuaText("私の宗教、世界、そして来世を正してください", "おおアッラーよ、私のすべての事柄を守る宗教を正してください。私の生計である世俗的な生活を正してください。そして私は来世を正しく設定し、そこに戻ります。生を私にとってあらゆる善の増加とし、死をあらゆる悪からの解放にしてください。", "宗教の改革、この世とあの世、この三つすべて。", "Prophet ﷺ の包括的なデュア。"),
        "dua_musarrifal_qulub" to DuaText("あなたの従順に心を向けてください", "おおアッラーよ、心を向ける方よ、私たちの心をあなたの従順に向けてください。", "従順に心を堅く保つためのデュア。", "すべての人々の心は慈悲深い神の二本の指の間にあります。"),
        "dua_jannah_nar" to DuaText("ジャンナを求めて火事から避難", "おおアッラーよ、私はあなたに楽園を求め、火からあなたに避難を求めます。", "タシャフドの後でも、いつでも。", "預言者 ﷺ はこう言いました：私たちのデュアもこれを中心に展開しています。"),
        "dua_khayri_kullih" to DuaText("今もこれからも大丈夫", "アッラーよ、私はあなたにすべての善を求めます ― 差し迫ったものと遅れたもの、私が知っていることと私が知らないこと ― そして私はすべての悪、差し迫ったものと遅れたもの、私が知っていることと私が知らないことからあなたに避難を求めます。アッラーよ、私はあなたに楽園を、そして私をそこに近づけてくれるどんな言葉や行為からもお願いします。私は火から、そして私をそれに近づけるどんな言葉や行為からも、あなたに避難を求めます。", "預言者 ﷺ はこの包括的なドゥアをアイシャ (RA) に教えました（ドゥアの一部）。", "あらゆる良いものを集めたデュア。"),
        "dua_ihdini_saddidni" to DuaText("私を導き、私をまっすぐに保ちなさい", "おおアッラーよ、私を導き、正しい道を歩ませてください。", "預言者 ﷺ はアリ (RA) にそれを教えました。", "ガイダンスは道に沿って導かれるもの、サダッドは矢の真っ直ぐさ、と考えてください。"),
        "dua_hubbaka" to DuaText("アッラーの愛を求めて", "おおアッラーよ、私はあなたの愛、あなたを愛する人々の愛、そして私をあなたの愛に導く行為をあなたに求めます。おおアッラーよ、あなたの愛を私自身、私の家族、そして冷たい水よりも大切にしてください。", "預言者 ﷺ によって関連付けられた Dawud (AS) のドゥア。", "アッラーの愛は最大の富です。"),
        "dua_filal_khayrat" to DuaText("善を行い悪を去る", "ああアッラーよ、私が善行を行い、悪行をやめ、貧しい人々を愛​​することができるようにしてください、そして私を許し、憐れんでくださいますようお願いします。そして、あなたが民を裁判にかけようとするときは、裁判を受けずに私を連れて行ってください。私はあなたの愛、あなたを愛する人々の愛、そして私をあなたの愛に近づける行為への愛をお願いします。", "アッラーは夢の中でこのドゥアを預言者 ﷺ に教えられました。", "預言者 ﷺ はこう言いました。「それは真実です。だから、それを学び、教えてください。」"),
        "dua_bi_ilmikal_ghayb" to DuaText("人生が良い間は生きさせてください", "おおアッラーよ、あなたの目に見えないものについての知識と創造物に対するあなたの力によって、あなたが私にとって生の方が良いと知っている限り私を生かし続けてください、そしてあなたが私にとって死の方が良いと知ったら私を連れて行ってください。アッラーよ、私はあなたに、私的にも公にもあなたを畏れ、満足のときも怒りのときも真理の言葉を、そして貧困のときも富のときも節制をお願いします。", "アンマル・イブン・ヤシル(RA)の祈りのドゥア（冒頭部分）。", "預言者 ﷺ は祈りの中でこのドゥアを行いました。"),
        "dua_ism_azam_mannan" to DuaText("イズム・エ・アザム：アル・マナン", "おおアッラーよ、私はあなたにお願いします。すべての賛美はあなたに属します。恩恵を与えてくださる方、天と地の創始者であるあなた以外に神はありません。おお威厳と名誉の所有者よ、永遠に生き続けるおお維持者よ！", "預言者 ﷺ は、この男はアッラーの偉大なる御名でドゥアを作ったと述べました。", "この名前で作成されたデュアに応答します。"),
        "dua_ism_azam_ahad_samad" to DuaText("イズム・エ・アザム：アル・アハド・アズ・サマド", "おおアッラーよ、私はあなたにお願いします。私はあなたがアッラーであることを証します。生むことも生まれることもない、自給自足者であるあなた以外に神はなく、神に匹敵する者は誰もいません。", "預言者 ﷺ は、この男はアッラーにその偉大なる御名を尋ねたと述べました。", "尋ねられると、神は答えます。それによって呼ばれると、神は答えます。"),
        "dua_thabbitni_hadiyan" to DuaText("私をしっかりさせ、導かれ、導き手になってください", "アッラーよ、私をしっかりとし、導き、導かれる者としてください。", "預言者 ﷺ はジャリール (RA) のためにこのドゥアを作りました (自分で「タビトニ」と言ってください)。", "Jarir (RA) の元のドゥアでは、「thabbit-hu」という単語が使用されています。"),
        "dua_rabbighfir_tub_alayya" to DuaText("私を許し、私の悔い改めを受け入れてください", "主よ、私を許し、私の悔い改めを受け入れてください。確かに、あなたは悔い改めを受け入れる方、慈悲深いお方です。", "一度に 100 回 — 預言者 ﷺ の実践。", "同胞団は預言者 ﷺ が一度に 100 回言ったことを数えました。"),
        "dua_rafiq_ala" to DuaText("死にゆく者のデュア", "おおアッラーよ、私を許し、私を憐れみ、最高の同伴者とともに私を加えてください。", "預言者 ﷺ の最後のドゥア — 病人が自分自身のために言うもの。", "預言者 ﷺ は、亡くなる際にこのドゥアを作成しました。"),
        "dua_la_bas_tahur" to DuaText("病人を慰める: 浄化", "害はありません。アッラーが御望みであれば、それは（罪からの）浄化である。", "お見舞いの際に病人を慰めるため。", "預言者 ﷺ は病人を見舞ったときにこう言いました。"),
        "dua_talqeen" to DuaText("死にゆく者のためのタルキーン", "アッラー以外に崇拝を受ける権利はありません。", "死にゆく人の近くでカリマーを唱えます（強制的に言わないでください）。", "最期の言葉が「ラ・イラハ・イラーラ」である者は誰でも楽園に入るであろう(Abu Dawud 3116)。"),
        "dua_ahyini_ma_kanat" to DuaText("死を望む代わりに", "おおアッラーよ、私にとって生が良い限り私を生かしてください、そして死が私にとって良いときは私を連れて行ってください。", "苦難の中で死を望むのではなく。", "預言者 ﷺ は死を願うことを禁じ、代わりにこれを教えました。"),
        "dua_for_one_i_cursed" to DuaText("言葉で傷つけた人のために", "おおアッラーよ、私が侮辱した信者よ、復活の日に彼があなたに近づく手段としてください。", "怒りのあまり悪口を言った相手に対して。", "Prophet ﷺ のデュア。"),
        "dua_praising_someone" to DuaText("誰かを褒めるとき", "私は誰々がこのようであると考えています、そしてアッラーは彼の清算者であり、アッラーの前で誰の純潔を私は保証しません。", "誰かを褒めるときは、大げさではなく。", "預言者 ﷺ はこの賛美の作法を教えました。"),
        "dua_being_praised" to DuaText("褒められたとき", "アッラーよ、彼らの言うことを私に考慮に入れないでください。そして彼らが知らないことを私にお許しください。", "自分が褒められるのを聞いて — コンパニオンの実践 (RA)。", "褒められたときに傲慢にならない方法。"),
        "dua_non_muslim_sneezes" to DuaText("非イスラム教徒がくしゃみをしたとき", "アッラーがあなたを導き、あなたの状況を正しく整えてくださいますように。", "非イスラム教徒がくしゃみをして「アルハムドゥリッラー」と言ったとき。", "ユダヤ人は預言者 ﷺ が「ヤルハムカラ」と言うだろうと期待して彼の近くでくしゃみをすると、彼はこう言うでしょう。"),
        "dua_reply_ahl_kitab_salam" to DuaText("本の人たちのサラームに返信する", "そしてあなたに。", "書の民がサラームで挨拶するとき。", "預言者ﷺの教え。"),
        "dua_fasting_invited" to DuaText("断食中に誘われたとき", "私は断食中です。", "断食中に誘われたとき、または誰かがあなたと喧嘩したとき。", "断食者が招待に応じた場合、主催者のために祈るべきです。"),
        "dua_for_who_gave_drink" to DuaText("私に食事を与えてくれた人のために", "おおアッラーよ、私に食べ物を与えてくれた人に食べ物を与え、私に飲み物を与えてくれた人に飲み物を与えてください。", "食べ物や飲み物をくれる人のために。", "預言者 ﷺ はアル・ミクダッド (RA) のためにこのドゥアを作りました。"),
        "dua_eid_greeting" to DuaText("イードの挨拶", "アッラーが私たちとあなたからの（善行を）受け入れてくださいますように。", "イードの日にお互いに — 高貴な同胞団の習慣 (RA)。", "同胞団はイードに集まったときにこう言いました。"),
        "dua_wedding_night" to DuaText("ニカ後の花嫁のために", "おおアッラーよ、私は彼女の善とあなたが彼女を創造された性質の善をあなたに祈り、彼女の悪とあなたが彼女を創造された性質の悪からあなたに避難を求めます。", "ニカの後、妻の額に手を置きます。", "預言者の ﷺ の教え — 結婚の祝福。"),
        "dua_istisqa_ibadak" to DuaText("使用人や動物に水をやる", "おおアッラーよ、あなたの僕たちとあなたの動物たちに水を与え、あなたの慈悲を広め、あなたの死んだ土地に命を与えてください。", "雨を乞う（イスティスカ）。", "預言者 ﷺ は雨のためにこのドゥアを作りました。"),
        "dua_seeing_clouds" to DuaText("暗い雲を見る", "おおアッラーよ、私はあなたにその悪からの避難を求めます。", "空に暗い雲が見えたとき。雨が降ったら、「Allahumma Sayyiban nafi'a」と言いましょう。", "雲を見ると、預言者 ﷺ は今までしていた作業をやめて、このドゥアを作りました。"),
        "dua_jamarat" to DuaText("ジャマラットに石を投げる", "アッラーは最も偉大な方です。", "小石を投げるたびに。", "預言者 ﷺ は、すべての小石でタクビルと言い、最初と 2 番目のジャムラの後、キブラに向かって長いドゥアを作りました。"),
        "dua_rabbi_ainni" to DuaText("主よ、私を助けてください、私に逆らわないでください", "私の主よ、私を助けてください、そして私に対して他の人を助けないでください、私に勝利を与えてください、そして他の人に私に対する勝利を与えないでください、私のために計画を立ててください、そして私に対して計画しないでください、私を導き、私にとって導きを容易にしてください、そして私を不当に扱う者に対して私を助けてください。", "Prophet ﷺ の包括的なデュア (冒頭部分)。", "宗教とこの世のあらゆる助けを集めるドゥア。"),
        "dua_ati_nafsi_taqwaha" to DuaText("グラント・マイ・ソウル・イッツ・タクワ", "おおアッラーよ、私の魂に敬虔さを与え、浄化してください。それを浄化するにはあなたが最善です。あなたはその守護者でありマスターです。", "自己改革と浄化に。", "Prophet ﷺ がこのデュアを作成していました。"),
        "dua_iqsim_lana_khashyatik" to DuaText("あなたに対するそのような恐れを私たちに与えてください", "ああアッラーよ、私たちとあなたに従わない私たちの間に入るのに十分なあなたへの恐れ、私たちをあなたの楽園に連れて行くのに十分な従順、そしてこの世界の災難を私たちにとって容易にするのに十分な確実性を与えてください。あなたが私たちを生かし、私たちよりも長生きさせてくださる限り、私たちの聴覚、視覚、そして強さを楽しみましょう。私たちを不当に扱った者たちに復讐し、私たちの敵に対して私たちを助け、私たちの災いを私たちの宗教の中に持ち込まないでください。この世界を私たちの最大の関心事や私たちの知識の限界にしないでください。そして、私たちに慈悲を示さない人々を私たちに押しつけないでください。", "集会から立ち上がるとき、預言者 ﷺ はこのデュアを行わずに立ち上がることはほとんどありませんでした。", "宗教、この世と来世のための包括的な二元論。"),
        "dua_infani_bima_allamtani" to DuaText("あなたが教えてくれたことを私に役立ててください", "おおアッラーよ、あなたが私に教えてくださったことで私を益し、私に益となることを教えて、私の知識を増やしてください。", "知識を求めているとき、または勉強する前に。", "有益な知識とそれに基づいた行動のためのデュア。"),
